# Valid Pages CMS schema, each text field independently editable
lines=['media:','  input: assets/uploads','  output: /assets/uploads','','content:']
def field(name,label,typ='string',indent=6):
    s=' '*indent
    return [f'{s}- name: {name}',f'{s}  label: {label}',f'{s}  type: {typ}']
for language,label in [('ar','النصوص العربية'),('en','English texts'),('fr','Textes français')]:
    lines += [f'  - name: texts_{language}',f'    label: {label}','    type: file',f'    path: content/texts/{language}.json','    format: json','    fields:']
    for key in texts[language]:
        lines+=field(key,key, 'text' if ('description' in key or 'text' in key or key in ('footer','privacy_text')) else 'string')
lines+=['  - name: settings','    label: الإعدادات والتصميم','    type: file','    path: content/site.json','    format: json','    fields:']
for key,val in site.items():
    typ=('image' if key in ('logo','hero_image','about_image') else 'boolean' if isinstance(val,bool) else 'number' if isinstance(val,int) else 'string')
    if key=='section_order':
        lines+=['      - name: section_order','        label: ترتيب الأقسام (اسحب لتغيير الترتيب)','        type: select','        list: true','        options:','          values:']
        lines+=['            - '+v for v in ['services','about','courses','books','private','institutions','contact']]
    else: lines+=field(key,key,typ)
for kind,label in [('courses','الكورسات'),('books','الكتب')]:
    lines += [f'  - name: {kind}',f'    label: {label}','    type: collection',f'    path: content/{kind}','    format: json','    filename: "{primary}.json"','    fields:']
    for key in ['title_ar','title_en','title_fr','description_ar','description_en','description_fr','image','price','url','language','published','order']:
        typ='image' if key=='image' else 'boolean' if key=='published' else 'number' if key=='order' else 'text' if key.startswith('description') else 'string'
        lines+=field(key,key,typ)
(P/'.pages.yml').write_text('\n'.join(lines)+'\n',encoding='utf8')
print('Created editable CMS settings, all three translation files, and initial products.')
